"""Materialize the 375-passage, four-pass source review of upper lessons 21--24.

Selections and qualifications below are manually authored from the fixed PDF.
SQLite is always opened mode=ro; writes are restricted to this 05 batch.
This script NEVER imports a batch or edits the shared package.
"""
import hashlib
import json
import re
import sqlite3
import sys
from collections import Counter, defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
OUT = Path(__file__).resolve().parent
KB = ROOT / 'shared-knowledge/v0.1.0'
DOC = 'volume_1-a53e99c37ca5'
BASE = '05-l021-l024-complete'
REVIEWER = 'Codex 主代理 / 阶段C上册21至24课同模型四轮复核'
SHA = 'a53e99c37ca500917ee5edf1d21efcb58f1b8e4363af2b4978dbdff920d18d4b'
db = sqlite3.connect((KB/'graph.sqlite').as_uri()+'?mode=ro',uri=True)
db.row_factory = sqlite3.Row
metadata = {r['key']:json.loads(r['value']) for r in db.execute('SELECT * FROM metadata')}
assert metadata['schema_version']=='1.1.0'
assert hashlib.sha256((KB/'sources/volume_1.pdf').read_bytes()).hexdigest()==SHA
passages = {r['id']:dict(r) for r in db.execute("SELECT * FROM passages WHERE unit_id IN ('lesson-021','lesson-022','lesson-023','lesson-024') ORDER BY pdf_page,block_index,id")}
assert len(passages)==375
source_snapshot = json.dumps(sorted(passages.values(),key=lambda p:p['id']),ensure_ascii=False,separators=(',',':'))
assert hashlib.sha256(source_snapshot.encode()).hexdigest()=='72e478dbefc5b648200e73fb2576b20aa75c6d07ec9dcc84f45a6b153021311b', 'Reviewed source passages changed; re-read before rebuilding.'
old = {r['id']:dict(r) for r in db.execute("SELECT * FROM claims WHERE review_status='reviewed'")}
concepts = {r['label']:dict(r) for r in db.execute('SELECT * FROM concepts')}
canonical = {label:r['label'] for r in concepts.values() for label in [r['label']]+json.loads(r['aliases'])}
figures = [dict(r) for r in db.execute('SELECT * FROM figures WHERE document_id=? AND pdf_page BETWEEN 104 AND 144 ORDER BY pdf_page,id',(DOC,))]
assert len(figures)==37
rows, pending, notes = [], [], {}
retained = defaultdict(list)

def pid(short):
    page,block = short.split('-',1)
    return f'{DOC}-p{int(page):04d}-{block}'

def ev(short,quote=None,figs=()):
    p=passages[pid(short)]
    # A few normalized blocks retain the NEXT header at their end. It is never
    # quoted as part of the preceding comment, even though source mapping exists.
    clean=re.sub(r'(?:\*+)?(?:2007-\d{2}-\d{2}\d{2}:\d{2}:\d{2})$','',p['text']).rstrip('*')
    quote=clean if quote is None else quote
    start=p['text'].find(quote)
    assert start>=0 and p['text'][start:start+len(quote)]==quote,(short,quote)
    return {'passage_id':p['id'],'quote':quote,'quote_start':start,'figure_ids':[f'{DOC}-p{int(n):04d}-fig{k}' for n,k in figs]}

def c(lesson,slug,shorts,text,labels,level,check,conditions=(),exceptions=(),figs=(),ambiguity='none',quotes=None):
    shortlist=shorts.split()
    citations=[ev(s,None if quotes is None else quotes[i],figs if i==0 else ()) for i,s in enumerate(shortlist)]
    cid=f'upper-l{lesson:03d}-c-stage-{slug}'
    assert cid not in old and cid not in {r['id'] for r in rows},cid
    labels=[canonical.get(x,x) for x in labels.split('|')]
    labels=list(dict.fromkeys(labels))
    ps=[passages[e['passage_id']] for e in citations]
    roles='/'.join(dict.fromkeys(p['role'] for p in ps))
    dates='/'.join(dict.fromkeys(p['published_at'] or '无单独日期' for p in ps))
    context=f'第{lesson}课{roles}；当前来源时间{dates}；' + check
    reasons={1:'基础核心：定义、定理或其不可省略的条件。',2:'主要方法：直接影响结构识别、比较或操作选择。',3:'补充深化：限定标准、方法适用范围或具体风险。',4:'背景细节：仅记录历史行情、预测、自述或方法论立场。'}
    r={'id':cid,'text':text,'kind':'explicit','conditions':list(conditions),'exceptions':list(exceptions),'concepts':labels,
       'ambiguity_status':ambiguity,'review_note':f'语境：{context}。适用条件：'+('；'.join(conditions) if conditions else '本条所列对象、级别及语境')+
       f'。四轮：完整阅读及上下问答；按独立结论拆解并保留联合前提；对照当前{len(old)}条reviewed命题和标准概念；逆向核对精确引文及原页。'+check+
       '。仅据固定汇编；模型四轮不是四名独立审查者，未核原博客。',
       'importance_level':level,'importance_reason':reasons[level]+check,'reviewer':REVIEWER,'evidence':citations,'relations':[]}
    if figs:
        r['figure_review_note']='主代理实际查看对应PDF原页；'+ ';'.join(figure_notes[(n,k)] for n,k in figs)+'。图中后加标线、嵌入文字及捕获日期不提升为作者原文；具体来源状态：'+ ';'.join(f['id']+'='+f['origin_status'] for f in figures if f['id'] in citations[0]['figure_ids'])+'。后加图与未核图均不作新增作者规则的唯一证据；文字证据独立支持命题。'
    rows.append(r)
    return cid

def keep(shorts,cids,reason):
    for s in shorts.split():
        for cid in cids.split():
            assert cid in old,cid
            retained[pid(s)].append(cid)
        notes[pid(s)]={'category':'existing_claim_retained','reading':reason,'inverse':reason}

def note(shorts,category,reading,inverse):
    for s in shorts.split(): notes[pid(s)]={'category':category,'reading':reading,'inverse':inverse}

def issue(slug,shorts,reason,action,blocker=False):
    pending.append({'id':'upper-l021-l024-c-stage-pending-'+slug,'status':'pending','passage_ids':[pid(s) for s in shorts.split()],
                    'description':reason,'suggested_action':action,'blocks_full_semantic_extraction_completion':blocker,'reviewer':REVIEWER})

