note('126-b003','learning_reminder','精确分析图形需要磨练的学习提示。','未给新图形判据；相关操作熟练要求已在已有及本批命题中记录。')
note('136-b001','historical_recap','作者回顾此前三角形后突破的判断。','不据原文自评或后加图认证预测准确率；下一段的调整阶段限定另抽。')
note('142-b006','partly_withheld','吻和中枢的工具定位可核；两次拉回的对象未保留。','仅发布有明确对象的工具定位；两次拉回保留为待核候选。')

by_passage=defaultdict(list)
for record in rows:
    for anchor in record['evidence']:
        by_passage[anchor['passage_id']].append(record)
for item in pending:
    item['lesson_numbers']=sorted({int(passages[x]['unit_id'].split('-')[1]) for x in item['passage_ids']})
    if item['id'].endswith('-figure-makers-and-annotations'):
        item['lesson_numbers']=[21,22,23,24]
        item['figure_ids']=[f['id'] for f in figures]

ledger=[]
for passage_id,p in passages.items():
    linked=by_passage[passage_id]
    retained_ids=retained.get(passage_id,[])
    decision=notes.get(passage_id)
    issues=[x['id'] for x in pending if passage_id in x['passage_ids']]
    if linked:
        result='new_claim'
        reading='；'.join(r['text'] for r in linked)
        atomic=[{'claim_id':r['id'],'conditions':r['conditions'],'exceptions':r['exceptions']} for r in linked]
        inverse='；'.join(r['review_note'] for r in linked)
    elif decision:
        result=decision['category'];reading=decision['reading'];atomic=[];inverse=decision['inverse']
    elif p['role']=='reader':
        result='reader_context';reading='已读该读者署名、提问或引述，供后续作者回答确定对象。';atomic=[]
        inverse='读者的前提、判断、成绩及其复制作者句子都保留reader身份，不直接作为作者证据。'
    elif p['role']=='unknown' and p['text']=='缠中说禅回复：':
        result='source_header';reading='回复栏目标题，未按实质发言归作者。';atomic=[];inverse='栏目名不支持技术命题。'
    elif p['text'].startswith('教你炒股票') or re.fullmatch(r'(?:缠中说禅(?:解盘)?[:：]?)?\d{4}-\d{2}-\d{2}.*',p['text']) or set(p['text'])=={'*'}:
        result='source_header';reading='课程标题、署名时间头或分隔符。';atomic=[]
        inverse='时间头只定位随后语境，排版标题/分隔不独立变成技术命题。'
    else:
        raise AssertionError(('unaccounted source paragraph',passage_id,p['text']))
    if decision and linked:
        reading+='；其余语境：'+decision['reading'];inverse+='；'+decision['inverse']
    ledger.append({'passage_id':passage_id,'lesson_number':int(p['unit_id'].split('-')[1]),'document_id':DOC,
        'pdf_page':p['pdf_page'],'role':p['role'],'speaker':p['speaker'],'published_at':p['published_at'],
        'source_text_sha256':hashlib.sha256(p['text'].encode()).hexdigest(),'result':result,
        'claim_ids':[r['id'] for r in linked],'related_existing_claim_ids':retained_ids,
        'existing_evidence_not_mutated':True,'pending_issue_ids':issues,'reviewer':REVIEWER,
        'rounds':{'1_read_and_scope':reading,'2_atomic_conditions':atomic,
            '3_normalization':{'concept_labels':sorted({x for r in linked for x in r['concepts']}),'related_existing_claim_ids':retained_ids,
                              'note':'原文与旧命题相关不代表条件完全相同；新增限定另列，旧证据未擅自追加。'},
            '4_reverse_check':inverse}})

for figure in figures:
    key=(figure['pdf_page'],int(figure['id'].rsplit('fig',1)[1]))
    figure.update(visual_review_complete=True,reviewer=REVIEWER,visual_review_note=figure_notes[key],
        figure_source_review='12个明确后加图见source-audit/stage-c-l021-l024-figure-applied.json；制作人均未核。',
        linked_claim_ids=[r['id'] for r in rows if any(figure['id'] in e['figure_ids'] for e in r['evidence'])])
assert len(ledger)==375 and len({x['passage_id'] for x in ledger})==375
def dump(suffix,data):
    (OUT/f'{BASE}.{suffix}').write_text('\n'.join(json.dumps(x,ensure_ascii=False,separators=(',',':')) for x in data)+'\n',encoding='utf-8')
dump('reviewed.jsonl',rows);dump('coverage.jsonl',ledger);dump('pending.jsonl',pending);dump('figures.jsonl',figures)
dump('withheld.jsonl',[{'candidate':r,'status':'pending','reason':'被回复的问题缺失，适用对象和级别未确认，不导入默认集合。'} for r in withheld])
summary={'stage':'C','schema_version':metadata['schema_version'],'graph_version':metadata['graph_version'],
    'lessons':[21,22,23,24],'document_id':DOC,'reviewer':REVIEWER,'passages_read':375,
    'claims':len(rows),'evidence':sum(len(r['evidence']) for r in rows),'importance_counts':dict(Counter(r['importance_level'] for r in rows)),
    'new_concepts':sorted({x for r in rows for x in r['concepts']}-set(concepts)),
    'whole_lesson_semantic_read_complete':True,'technical_extraction_complete':False,'four_round_review':True,
    'independent_review_claimed':False,'visual_pdf_pages':list(range(104,145)),'figure_objects_viewed':37,
    'figure_origin_counts':dict(Counter(f['origin_status'] for f in figures)),
    'pending':[x['id'] for x in pending],'withheld_default_claims':len(withheld),
    'source_passages_snapshot_sha256':'72e478dbefc5b648200e73fb2576b20aa75c6d07ec9dcc84f45a6b153021311b',
    'retained_source_links_in_ledger_only':True,'database_mode':'ro','formal_import':False,
    'acceptance':'375段四轮审读及41页37图检查完成；明确文字命题待预检发布，未答题/缺失问题/参照层次和图源等分别待核。'}
(OUT/f'{BASE}.summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
db.close();sys.stdout.reconfigure(encoding='utf-8');print(json.dumps(summary,ensure_ascii=False))
